def x2611_15723_descents {n : ℕ} (π : Equiv.Perm (Fin n)) : Finset ℕ :=
  (Finset.univ.filter (fun i : Fin n =>
    ∃ j : Fin n, j.val = i.val + 1 ∧ π j < π i)).image (fun i => i.val + 1)

def x2611_15723_qchoose (q : ℚ) (n k : ℕ) : ℚ :=
  ∑ S ∈ (Finset.range n).powersetCard k,
    q ^ ((∑ i ∈ S, i) - k * (k - 1) / 2)

def x2611_15723_psi (q : ℚ) (n : ℕ) (J : Finset ℕ) : PowerSeries ℚ :=
  PowerSeries.mk (fun m =>
    x2611_15723_fundamental m n J (fun i => q ^ i.val))
